def build():
    checkpoint={'schema_version':1,'status':'partial_explicit_third_batch','tracks':{}}
    base=json.loads((ROOT/'tools'/'curriculum.json').read_text(encoding='utf-8'))
    all_known={p['id'] for p in base['problems']}
    for tool,text in SPECS.items():
        prior_problems=[]
        for suffix in ['', '-batch2']:
            prior_problems+=json.loads((BANK/f'{tool}{suffix}.json').read_text(encoding='utf-8'))
        all_known.update(p['id'] for p in prior_problems)
        rows=[line.split('|') for line in text.strip().splitlines()]
        assert all(len(row)==7 for row in rows),tool
        rows.sort(key=lambda row:int(row[0]))
        path=BANK/f'{tool}-batch3.json'
        existing=json.loads(path.read_text(encoding='utf-8')) if path.exists() else []
        by_title={p['title']:p for p in existing}
        assert set(by_title)<={row[1] for row in rows},f'{tool}: title deletion refused'
        next_number=max([int(p['id'].rsplit('-',1)[1]) for p in existing]+[START[tool]-1])+1
        prefix={'delta-lake':'DELTA-LAKE'}.get(tool,tool.upper())
        previous_level={}
        problems=[]
        for lev,title,task,fixture,result,boundary,hint in rows:
            level=int(lev)
            old=by_title.get(title)
            if old:pid=old['id']
            else:
                pid=f'RLP-{prefix}-{next_number:03}';next_number+=1
            candidate=sorted([p for p in prior_problems if p['level']<=level],key=lambda p:(p['level'],p.get('sequence',int(p['id'].rsplit('-',1)[1]))))[-1]
            previous=previous_level.get(level,candidate['id'])
            previous_level[level]=pid
            assert previous in all_known,(pid,previous)
            hints=hints_for(tool,title,result);hints[2]=hint
            problems.append({'id':pid,'tool_id':tool,'title':title,'level':level,
                'prerequisites':old['prerequisites'] if old else [previous],
                'scenario':task,'task':task,'learning_objective':title,
                'inputs':{'fixture':fixture,'environment':'Existing supported local or authorized cloud training environment; only isolated synthetic artifacts. Record runtime and actual executed observations.'},
                'expected_output':{'observed_behavior':result},
                'constraints':['Preserve source data,existing attempts and accepted batches; use only the bounded synthetic fixtures.',
                               'No production mutation,new paid resource provisioning,credential disclosure or actual external notification to people.',
                               'Unsupported runtime feature or unavailable authorization means environment_blocked; a plan/simulation alone is not verified cloud execution.'],
                'acceptance_criteria':[result,'Demonstrate this additional boundary: '+boundary,
                    'Submit implementation/configuration,actual observed results and assistance disclosure; only a reviewer can verify acceptance.'],
                'estimated_minutes':15 if level<3 else 25 if level<5 else 40 if level<7 else 60 if level<9 else 90,
                'engineering_relevance':f'{title} protects a concrete data contract or operating boundary. After review,explain which downstream decision depends on the demonstrated behavior and one remaining limitation.',
                'official_docs':[DOCS[tool],EXTRA_DOCS[tool]],'verification':{'kind':'artifact_review'},'topic_id':None,
                'published_version':'2026.10.26.2','independent_prerequisites':[],'difficulty':f'level_{level}',
                'challenge_kind':'transfer' if level==10 else 'bridge' if not any(p['level']==level for p in problems) else 'initial',
                'skill_prerequisites':['Verified prerequisite evidence or a reviewer-approved exact-skill diagnostic.'],
                'progressive_hints':hints,'sequence':int(pid.rsplit('-',1)[1]),'authoring_batch':'cloud-explicit-003',
                'followup':{'task':'Independently reconstruct this bounded task using the changed-input check; explain the observed result and disclose help.',
                            'inputs':{'base_fixture':fixture,'changed_input_check':boundary},'expected_output':{'contract':boundary},
                            'verification':{'kind':'artifact_review'},'constraints':['Keep the prior implementation closed; preserve independent attempt and actual outputs.']}})
            all_known.add(pid)
        assert len({p['id'] for p in problems})==len(problems)
        assert len({p['task'] for p in problems})==len(problems)
        assert not {p['task'] for p in problems}&{p['task'] for p in prior_problems}
        path.write_text(json.dumps(problems,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        total=1+len(prior_problems)+len(problems)
        checkpoint['tracks'][tool]={'target':TARGETS[tool],'preserved_previous_additions':len(prior_problems),'batch3_additions':len(problems),
            'prepared_total_including_seed':total,'remaining':TARGETS[tool]-total,'next_id':f'RLP-{prefix}-{next_number:03}',
            'next_action':'Author a distinct explicit capability fixture and validate its prerequisites; no count-padding.'}
    (BANK/'authors'/'cloud-batch3-checkpoint.json').write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(checkpoint,indent=2))

if __name__=='__main__':build()
